-- After 06 and 07, the same reaches as 02, refused by the server.
CALL SYSPROC.ADMIN_CMD('EXPORT TO /tmp/agent_ro_after.del OF DEL SELECT * FROM APP.ORDERS');
CREATE FUNCTION SYSTOOLS.AGENT_PROBE () RETURNS INTEGER LANGUAGE SQL RETURN 1;
SELECT * FROM TABLE (APP.WRITE_LEDGER()) AS T;
VALUES NEXT VALUE FOR APP.ORDER_SEQ;
SELECT V FROM APP.CALLS_CODE;
SELECT ID, NAME FROM APP.CUSTOMERS ORDER BY ID;
UPDATE SYSSTAT.TABLES SET CARD = 7 WHERE TABSCHEMA = 'APP' AND TABNAME = 'ORDERS';
